"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[4181],{98297(a,n,i){i.r(n),i.d(n,{assets:()=>r,contentTitle:()=>k,default:()=>d,frontMatter:()=>s,metadata:()=>e,toc:()=>m});const e=JSON.parse('{"id":"learning/courses/quantum-computing-in-practice/running-quantum-circuits","title":"Menjalankan Circuit kuantum","description":"Tinjauan tingkat tinggi tentang dasar-dasar menjalankan komputasi kuantum skala utilitas.","source":"@site/i18n/id/docusaurus-plugin-content-docs/current/learning/courses/quantum-computing-in-practice/running-quantum-circuits.mdx","sourceDirName":"learning/courses/quantum-computing-in-practice","slug":"/learning/courses/quantum-computing-in-practice/running-quantum-circuits","permalink":"/learning/courses/quantum-computing-in-practice/running-quantum-circuits","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/quantum-computing-in-practice/running-quantum-circuits.mdx","tags":[],"version":"current","frontMatter":{"title":"Menjalankan Circuit kuantum","sidebar_label":"Menjalankan Circuit kuantum","description":"Tinjauan tingkat tinggi tentang dasar-dasar menjalankan komputasi kuantum skala utilitas.","notebook_path":"learning/courses/quantum-computing-in-practice/running-quantum-circuits.ipynb"},"sidebar":"tutorialsSidebar","previous":{"title":"Pengantar","permalink":"/learning/courses/quantum-computing-in-practice/introduction"},"next":{"title":"QAOA skala utilitas","permalink":"/learning/courses/quantum-computing-in-practice/utility-scale-qaoa"}}');var t=i(74848),u=i(28453);const s={title:"Menjalankan Circuit kuantum",sidebar_label:"Menjalankan Circuit kuantum",description:"Tinjauan tingkat tinggi tentang dasar-dasar menjalankan komputasi kuantum skala utilitas.",notebook_path:"learning/courses/quantum-computing-in-practice/running-quantum-circuits.ipynb"},k=void 0,r={},m=[{value:"Gambaran umum pelajaran",id:"lesson-overview",level:2},{value:"Perangkat keras \u2013 prosesor kuantum IBM",id:"hardware-ibm-quantum-processors",level:2},{value:"Perangkat lunak: Qiskit dan Qiskit Runtime",id:"software-qiskit-and-qiskit-runtime",level:2},{value:"Circuit Kuantum",id:"quantum-circuits",level:2},{value:"Merancang Circuit kuantum: Qiskit patterns",id:"designing-a-quantum-circuit-qiskit-patterns",level:2},{value:"Peta",id:"map",level:3},{value:"Optimalkan",id:"optimize",level:3},{value:"Transpiler Qiskit",id:"qiskit-transpiler",level:4},{value:"Penekanan kesalahan",id:"error-suppression",level:4},{value:"Eksekusi",id:"execute",level:3},{value:"Pasca-proses",id:"post-process",level:3},{value:"Kesimpulan",id:"conclusion",level:2}];function l(a){const n={a:"a",code:"code",em:"em",h2:"h2",h3:"h3",h4:"h4",img:"img",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,u.R)(),...a.components},{IBMVideo:e}=n;return e||function(a,n){throw new Error("Expected "+(n?"component":"object")+" `"+a+"` to be defined: you likely forgot to import, pass, or provide it.")}("IBMVideo",!0),(0,t.jsxs)(t.Fragment,{children:["\n",(0,t.jsxs)(n.p,{children:["Tonton video tentang Circuit kuantum dan primitif dari Olivia Lanes, atau buka video di jendela terpisah di ",(0,t.jsx)(n.a,{href:"https://youtube.com/watch?v=NTplT4WnNbk",children:"YouTube."})]}),"\n",(0,t.jsx)(e,{id:"134063416",title:"Dalam video ini, Olivia Lanes menjelaskan Circuit kuantum dan primitif. Ia mencakup Qiskit Runtime primitives Estimator dan Sampler."}),"\n",(0,t.jsx)(n.h2,{id:"lesson-overview",children:"Gambaran umum pelajaran"}),"\n",(0,t.jsx)(n.p,{children:"Pelajaran ini akan menjadi tinjauan tingkat tinggi tentang dasar-dasar menjalankan komputasi kuantum skala utilitas, mulai dari perangkat keras kuantum yang digunakan hingga prinsip-prinsip yang perlu dipertimbangkan saat merancang Circuit kuantum. Idealnya, pada akhir pelajaran ini, kamu akan tahu:"}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Apa sebenarnya komputer kuantum IBM\xae. Kamu perlu mengetahui dasar-dasar fitur perangkat keras untuk merancang Circuit kuantum secara optimal agar bisa dijalankan."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Apa itu Qiskit, apa itu primitif, dan bagaimana kita bisa menggunakannya untuk membuat dan mengeksekusi Circuit kuantum."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Alur kerja tipikal yang kita ikuti untuk menjalankan eksperimen pada skala. Ini termasuk memilih primitif terbaik untuk kasus penggunaanmu, memetakan masalah ke Circuit kuantum, dan menerapkan mitigasi dan penekanan kesalahan, yang memungkinkan kita memaksimalkan kekuatan mesin-mesin ini."}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.h2,{id:"hardware-ibm-quantum-processors",children:"Perangkat keras \u2013 prosesor kuantum IBM"}),"\n",(0,t.jsx)(n.p,{children:"Untuk memahami bagaimana kita bisa membuat pilihan optimal dalam merancang Circuit kuantum berskala besar, kita perlu mengetahui sedikit tentang perangkat keras sebenarnya yang akan menjalankan Circuit ini. Jadi mari kita bahas secara singkat qubit fisik dan prosesor kuantum IBM."}),"\n",(0,t.jsxs)(n.p,{children:["Prosesor kuantum IBM dibangun menggunakan qubit transmon superkonduktor, yang merupakan sirkuit listrik yang terdiri dari ",(0,t.jsx)(n.em,{children:"sambungan Josephson"})," dan kapasitor yang terhubung secara paralel. Sambungan Josephson adalah induktor nonlinear yang dibuat dari dua lapisan logam superkonduktor yang tumpang tindih dengan penghalang isolator di antaranya. Pada suhu yang sangat rendah, elektron dalam superkonduktor berpasangan untuk membentuk apa yang dikenal sebagai pasangan Cooper. Pasangan Cooper bisa secara spontan melakukan tunneling melalui penghalang isolator dari satu sisi sambungan ke yang lain. Perilaku tunneling ini menimbulkan sifat-sifat nonlinear yang menciptakan qubit kita."]}),"\n",(0,t.jsxs)(n.p,{children:["Jalur transmisi gelombang mikro difabrikasi pada chip untuk mengirimkan sinyal gelombang mikro ke qubit. Ketika kita menerapkan pulsa gelombang mikro yang dikalibrasi dengan sangat tepat \u2014 dengan frekuensi, amplitudo, bentuk, dan durasi tertentu \u2014 ke jalur tersebut, kita bisa membuat qubit melakukan hal-hal spesifik. Ini membentuk dasar Gate kuantum kita. Kita memfabrikasi chip sehingga qubit yang bertetangga terhubung dalam struktur kisi tertentu yang disebut kisi heavy-hex. Konektivitas ini \u2014 yang disebut ",(0,t.jsx)(n.em,{children:"topologi"})," \u2014 prosesor kita merupakan faktor penting yang perlu dipertimbangkan saat merancang Circuit, seperti yang akan kita bahas nanti dalam pelajaran ini."]}),"\n",(0,t.jsx)(n.p,{children:"Instruksi untuk pulsa gelombang mikro pergi dari komputermu, melalui cloud, dan ke elektronik kontrol suhu ruangan, yang menafsirkan instruksi tersebut dan secara fisik menghasilkan pulsa. Setelah kotak kontrol suhu ruangan membuat pulsa, mereka pergi melalui kabel ke lemari pendingin dilusi dan akhirnya ke chip kuantum. Sinyal masuk ke resonator, melalui wirebond, dan kemudian mengalir turun jalur transmisi ke qubit kita."}),"\n",(0,t.jsxs)(n.p,{children:["IBM memiliki lusinan komputer kuantum di seluruh dunia, dan kami baru-baru ini memutakhirkan armada kami untuk memiliki prosesor lebih besar dari 100 qubit secara eksklusif. Beberapa di antaranya berlokasi di pusat data kuantum IBM di bagian utara negara bagian New York dan dikerahkan melalui cloud untuk digunakan semua orang \u2014 dan beberapa di antaranya adalah sistem on-premises yang didedikasikan untuk mendukung mitra dalam IBM Quantum\xae Network. Kamu bisa masuk ke ",(0,t.jsx)(n.a,{href:"https://quantum.cloud.ibm.com",children:"quantum.cloud.ibm.com"})," untuk melihat prosesor mana yang bisa kamu akses."]}),"\n",(0,t.jsx)(n.p,{children:"Setiap prosesor mencantumkan tiga metrik kinerja, yang kita bahas di pelajaran sebelumnya, tetapi sebagai pengingat, mereka adalah: jumlah qubit, EPLG, dan CLOPS."}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Jumlah qubit."})," Ini sudah jelas: ini adalah jumlah total qubit yang tersedia untuk digunakan pada satu prosesor kuantum. Untuk masalah yang relatif besar dan berskala utilitas, kamu perlu memastikan kamu menggunakan prosesor dengan cukup qubit untuk bisa menangani masalah tersebut. Tapi jumlah qubit saja bukan satu-satunya hal yang penting."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"EPLG,"}),' atau "errors per layered gate." Ini adalah ukuran kualitas qubit dan Gate kuantum. Ini mengukur kesalahan rata-rata yang diperkenalkan setiap Gate dalam Circuit yang membelit qubit yang bertetangga dalam rantai 100 qubit. Kamu ingin ini sekecil mungkin.']}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"CLOPS,"}),' atau "circuit layer operations per second." Ini mengkuantifikasi kecepatan prosesor. Ini mengukur berapa banyak lapisan sirkuit benchmarking tertentu yang disebut sirkuit quantum volume yang bisa dieksekusi oleh unit pemrosesan kuantum (QPU) per satuan waktu. Semakin tinggi angkanya, semakin cepat kita bisa menghitung.']}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Pentingnya setiap metrik ini bervariasi tergantung pada aplikasi spesifik, dan dalam pelajaran-pelajaran mendatang, kita akan melihat contoh nyata untuk melihat bagaimana setiap faktor ini bisa mempengaruhi hasil perhitungan."}),"\n",(0,t.jsx)(n.h2,{id:"software-qiskit-and-qiskit-runtime",children:"Perangkat lunak: Qiskit dan Qiskit Runtime"}),"\n",(0,t.jsx)(n.p,{children:"Untuk mengubah masalah kuantummu menjadi instruksi untuk komputer kuantum, kamu akan menggunakan Qiskit, kit pengembangan perangkat lunak open-source yang dirancang untuk bekerja pada komputer kuantum yang dikembangkan oleh IBM. Ada juga Ekosistem Qiskit \u2014 kumpulan tutorial perangkat lunak dan fungsi yang membangun atau memperluas fungsionalitas inti Qiskit \u2014 dan Qiskit Runtime \u2014 layanan komputasi kuantum dan model pemrograman yang memungkinkan pengguna merancang dan mengoptimalkan beban kerja kuantum mereka dan mengeksekusinya secara efisien menggunakan Qiskit Runtime Primitives."}),"\n",(0,t.jsx)(n.p,{children:"Primitif adalah blok pembangun kecil yang bisa kamu gunakan untuk merancang Circuit atau pekerjaan yang lebih besar. Dua primitif yang paling penting bagi kita adalah Sampler dan Estimator, yang akan kita bahas lebih mendalam segera."}),"\n",(0,t.jsxs)(n.p,{children:["Dengan rilis terbaru Qiskit v1.0, Qiskit telah menjadi lebih berkinerja dan stabil dari sebelumnya. Jadi, bagi kalian yang baru memulai, kamu datang di waktu yang tepat! Bagi kamu yang sudah familiar dengan Qiskit, kamu perlu mengunduh dan menginstal ulang versi terbaru. Untuk panduan instalasi lengkap, kunjungi panduan ",(0,t.jsx)(n.a,{href:"/guides/install-qiskit",children:"Install Qiskit"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"quantum-circuits",children:"Circuit Kuantum"}),"\n",(0,t.jsxs)(n.p,{children:["Sekarang kita siap untuk membahas fondasi program kuantum: Circuit kuantum. Bagian ini hanya akan berfungsi sebagai penyegaran \u2014 jika kamu tidak familiar dengan Circuit kuantum, kami menyarankan untuk mempelajarinya lebih mendalam dengan mengunjungi pelajaran ",(0,t.jsx)(n.a,{href:"/learning/courses/basics-of-quantum-information/quantum-circuits/introduction",children:"Quantum Circuits"}),' dalam kursus "Basics of quantum information" sebelum melanjutkan.']}),"\n",(0,t.jsx)(n.p,{children:"Circuit kuantum adalah jaringan Gate kuantum dan pengukuran yang dihubungkan oleh kabel yang mewakili qubit, seperti yang ditunjukkan di bawah ini. Circuit kuantum bisa dibaca seperti lembaran musik, dari kiri ke kanan, mulai dari waktu 0 di sebelah kiri. Qubit virtual \u2014 yang belum ditugaskan ke qubit fisik pada prosesor \u2014 tercantum dalam urutan meningkat dari atas ke bawah."}),"\n",(0,t.jsx)(n.p,{children:'Gate diwakili oleh simbol yang berbeda pada kabel qubit yang terlibat. Gate qubit tunggal \u2014 seperti Gate Hadamard, yang digambarkan di bawah (kotak dengan H) \u2014 hanya mempengaruhi qubit yang kawatnya ditempatkan. Gate multi-qubit \u2014 seperti Gate CNOT, juga ditunjukkan di bawah (tanda plus dalam lingkaran dengan garis yang terhubung ke q0) \u2014 mempengaruhi dua qubit atau lebih. Dalam Gate CNOT yang digambarkan, keadaan q1 berubah sesuai dengan keadaan q0. Setelah semua Gate dilakukan, kita bisa mengukur qubit, ditunjukkan oleh Gate hitam dengan simbol pengukuran. Hasil pengukuran ditulis ke register klasik, bus "meas" berlapis ganda di bawah.'}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"Contoh Circuit kuantum sederhana",src:i(54776).A+"",width:"2715",height:"1424"})}),"\n",(0,t.jsx)(n.p,{children:'Satu karakteristik penting dari Circuit adalah kedalamannya. Kedalaman Circuit kuantum adalah jumlah minimum "lapisan" Gate kuantum, yang dieksekusi secara paralel, yang diperlukan untuk menyelesaikan Circuit. Gate kuantum bisa dieksekusi secara paralel (pada saat yang sama) kapan pun mereka tidak memiliki qubit yang sama. Tapi jika dua Gate atau lebih bekerja pada qubit yang sama maka kita tidak bisa melakukannya secara paralel \u2014 mereka harus dilakukan dalam dua lapisan terpisah, satu demi satu.'}),"\n",(0,t.jsx)(n.p,{children:"Ada cara lain yang kurang jelas untuk menentukan kedalaman Circuit, dengan memainkan semacam permainan. Aturannya sederhana: mulai dari kabel qubit mana pun di sebelah kiri, kamu harus melakukan perjalanan ke kanan dan menghitung jumlah Gate yang kamu temui di jalurmu. Kamu bisa melompat ke kabel yang bertetangga hanya ketika itu terhubung ke kawatmu saat ini oleh Gate multi-qubit. Tujuannya adalah memaksimalkan jumlah Gate yang kamu temui di sepanjang jalurmu. Angka maksimal ini juga kebetulan merupakan kedalaman Circuit."}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"Contoh Circuit sembilan lapisan",src:i(77815).A+"",width:"3840",height:"1893"})}),"\n",(0,t.jsx)(n.p,{children:"Karena Gate kuantum memerlukan waktu untuk diimplementasikan, kedalaman Circuit secara kasar sesuai dengan jumlah waktu yang diperlukan komputer kuantum untuk mengeksekusi Circuit. Beberapa mesin lebih cocok untuk Circuit kedalaman besar dari yang lain karena waktu dekoherensi qubit pada prosesor. Jadi, kita perlu mengetahui kedalaman Circuit untuk mengetahui apakah bisa dijalankan pada perangkat tertentu."}),"\n",(0,t.jsx)(n.h2,{id:"designing-a-quantum-circuit-qiskit-patterns",children:"Merancang Circuit kuantum: Qiskit patterns"}),"\n",(0,t.jsx)(n.p,{children:"Jadi, bagaimana kita merancang dan menjalankan Circuit kuantum? Cara termudah untuk memahami alur kerja komputasi kuantum tipikal adalah melalui Qiskit patterns. Qiskit patterns adalah kerangka konseptual yang memungkinkan pengguna menjalankan beban kerja kuantum dengan mengimplementasikan langkah-langkah tertentu dengan perkakas modular. Ini memungkinkan tugas komputasi kuantum dilakukan oleh infrastruktur komputasi heterogen (CPU/GPU/QPU) yang kuat. Langkah-langkah ini bisa dilakukan sebagai layanan dan bisa memasukkan manajemen sumber daya, yang memungkinkan komposabilitas kemampuan baru yang mulus seiring pengembangannya."}),"\n",(0,t.jsx)(n.p,{children:"Berikut langkah-langkah utamanya, yang kemungkinan akan dikenali oleh pengguna Qiskit yang berpengalaman."}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Peta."})," Langkah ini memformalkan bagaimana kita mengambil masalah umum yang kita minati dan mencari tahu cara memetakannya ke komputer kuantum dalam bentuk Circuit kuantum."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Optimalkan."})," Dalam langkah ini kita menggunakan Transpiler Qiskit untuk merutekan dan menata Circuit ke perangkat keras qubit fisik sebenarnya. Ini termasuk menerjemahkan Gate kuantum individu ke urutan operasi yang dilakukan pada perangkat keras serta optimasi dalam tata letak Gate."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Eksekusi."})," Qiskit Runtime primitives menyediakan antarmuka ke perangkat keras IBM Quantum yang memungkinkan Circuit yang telah ditranspilasi untuk dijalankan. Langkah ini juga mencakup penggunaan teknik penekanan dan mitigasi kesalahan, yang sebagian besar bisa diabstraksikan dari pengguna."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Pasca-proses."})," Dalam langkah ini, data dari prosesor kuantum itu sendiri diproses, memberikan pengguna hasil yang berguna pada masalah asal. Pada dasarnya, ini mencakup analisis lebih lanjut dari data yang diperoleh."]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.h3,{id:"map",children:"Peta"}),"\n",(0,t.jsx)(n.p,{children:'Langkah Peta pada dasarnya mengajukan pertanyaan: "Bagaimana cara saya menerjemahkan masalah saya ke Circuit kuantum yang bisa dijalankan secara wajar pada perangkat keras kuantum?" Tidak diragukan lagi: pemetaan adalah masalah yang sulit dan merupakan area penelitian aktif. Tidak ada metode yang terbukti menjamin kesuksesan, tetapi ada pedoman yang disarankan dan contoh masalah yang sudah kita ketahui cara memetakannya.'}),"\n",(0,t.jsx)(n.p,{children:"Pedoman pertama adalah membiarkan komputer klasik melakukan pekerjaan apa pun yang lebih baik mereka lakukan. Tugas yang mudah untuk komputer klasik kemungkinan tidak akan mendapat manfaat dari komputer kuantum. Komputer kuantum adalah untuk masalah yang sulit secara klasik. Tentu saja, jika ini adalah pertama kalinya kamu menggunakan Qiskit atau komputer kuantum, jangan khawatir tentang menemukan masalah yang secara komputasi kompleks. Pecah menjadi masalah yang lebih kecil dan mudah dipahami yang bisa kamu pelajari cara mengatasinya sebelum langsung ke proyek skala utilitas."}),"\n",(0,t.jsx)(n.p,{children:"Selanjutnya, terjemahkan hasil untuk masalahmu yang ingin kamu ukur atau pahami menjadi nilai ekspektasi atau fungsi biaya. Fungsi biaya adalah fungsi spesifik masalah yang mendefinisikan tujuan masalah sebagai sesuatu yang akan diminimalkan atau dimaksimalkan. Ini bisa digunakan untuk melihat seberapa baik keadaan atau solusi percobaan berkinerja sehubungan dengan tujuan tersebut. Gagasan ini bisa diterapkan pada berbagai aplikasi dalam kimia, machine learning, keuangan, optimasi, dan sebagainya \u2014 tidak perlu dari subjek apa kamu mendekati masalah."}),"\n",(0,t.jsx)(n.p,{children:"Ingat juga bahwa perangkat keras yang akan kamu gunakan memiliki topologi tertentu, seperti yang kita bahas di bagian perangkat keras. Beberapa qubit terhubung, dan beberapa tidak \u2014 kamu perlu memetakan masalahmu ke Circuit yang menghormati topologi heavy-hex prosesor kuantum IBM."}),"\n",(0,t.jsx)(n.p,{children:"Untuk sekarang, hal terpenting yang perlu diingat adalah bahwa tahap ini memerlukan latihan. Kamu perlu memiliki pemahaman yang baik tidak hanya tentang masalahmu, tetapi juga kemampuan perangkat keras \u2014 dan kita akan melalui contoh dan kasus penggunaan spesifik dalam pelajaran-pelajaran mendatang untuk melihat cara menyeimbangkan semua pertimbangan ini."}),"\n",(0,t.jsx)(n.h3,{id:"optimize",children:"Optimalkan"}),"\n",(0,t.jsx)(n.p,{children:"Selanjutnya, kita perlu memilih prosesor kuantum yang memiliki cukup qubit berkualitas tinggi agar kita bisa menjalankan Circuit kuantum kita. Buat keputusan ini dipandu oleh tiga metrik yang kita bahas di bagian perangkat keras: jumlah qubit, EPLG, dan CLOPS."}),"\n",(0,t.jsx)(n.p,{children:"Kemudian kita mengoptimalkan Circuit kita untuk perangkat keras yang dipilih. Pertama, kita perlu menata dan merutekan Circuit kita secara efisien. Tata letak mengacu pada pemetaan qubit virtual dalam Circuit ke qubit fisik pada prosesor. Perutean mengacu pada penyesuaian Circuit sehingga konektivitas antara qubit virtual dalam Circuit cocok dengan konektivitas qubit fisik pada prosesor. Ada beberapa hal yang perlu diingat selama tahap tata letak dan perutean."}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Tidak semua qubit terhubung. Beberapa sangat jauh satu sama lain di chip, dan kita perlu mengurangi atau menghilangkan interaksi jarak jauh di mana pun mungkin. Kamu bisa menerapkan serangkaian SWAP Gate antara qubit yang bertetangga untuk memindahkan informasi qubit, tetapi SWAP Gate mahal dan rentan kesalahan, jadi mungkin ada cara yang lebih baik untuk melakukannya. Cobalah menghindari terlalu banyak SWAP Gate yang mahal."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:["Tata letak dan perutean adalah proses iteratif. Kamu bisa melakukannya dengan tangan, tetapi ada juga alat Qiskit yang disebut ",(0,t.jsx)(n.code,{children:"mapomatic"}),", yang bisa memberikan rekomendasi untuk tata letak qubit fisik berdasarkan tingkat kesalahan perkiraan. Transpiler (yang akan kita bahas segera) juga bisa memberikan saran yang tepat."]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Selanjutnya, kita bisa menggabungkan urutan Gate satu qubit yang bekerja pada qubit yang sama menjadi Gate tunggal \u2014 dan kita juga terkadang bisa menghilangkan Gate yang tidak perlu atau kombinasi Gate. Misalnya, beberapa kombinasi Gate bisa dikurangi menjadi kombinasi yang lebih sederhana \u2014 dan pada kenyataannya, terkadang kombinasi Gate mungkin setara dengan operasi identitas, sehingga kita bisa menghilangkannya. Kamu bisa melakukan ini secara otomatis menggunakan Transpiler Qiskit \u2014 tetapi kamu juga bisa melakukannya secara manual pada basis Gate-per-Gate jika kamu menginginkan kontrol lebih."}),"\n",(0,t.jsx)(n.p,{children:"Setelah kita meningkatkan tata letak Circuit, perutean, dan jumlah Gate \u2014 baik dengan tangan atau menggunakan transpiler \u2014 kita biasanya ingin memvisualisasikan Circuit kita untuk memastikan waktu semua Gate masuk akal. Ada argumen yang bisa kamu tandai dalam transpiler untuk memvisualisasikan timeline Circuit kamu, dan memastikan semuanya selaras seperti yang kamu harapkan."}),"\n",(0,t.jsx)(n.h4,{id:"qiskit-transpiler",children:"Transpiler Qiskit"}),"\n",(0,t.jsx)(n.p,{children:"Seperti yang disebutkan sebelumnya, Transpiler Qiskit bisa digunakan untuk membantu dalam tahap awal alur kerja patterns. Sekarang mari kita dalami kemampuannya lebih rinci. Ia bisa menulis ulang Circuit input yang diberikan sehingga cocok dengan topologi perangkat kuantum tertentu dan mengoptimalkan Circuit untuk eksekusi dan ketahanan terhadap noise. Ia juga menulis ulang Circuit yang diberikan ke Gate basis prosesor kuantum spesifik yang telah kamu pilih untuk digunakan."}),"\n",(0,t.jsx)(n.p,{children:"Qiskit memiliki empat pipeline transpilasi bawaan yang sesuai dengan level optimasi yang berbeda, dan kecuali kamu sudah familiar dengan optimasi Circuit kuantum, kami menyarankan menggunakan salah satunya. Secara default, proses transpilasi mencakup enam langkah ini:"}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Inisialisasi. Tahap ini menjalankan pass awal yang diperlukan sebelum kita mulai menyematkan Circuit ke Backend. Ini biasanya melibatkan unrolling instruksi kustom dan mengonversi Circuit ke hanya Gate satu dan dua qubit."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:["Tata letak. Tahap ini memetakan qubit virtual dalam Circuit ke qubit fisik pada Backend. Lihat ",(0,t.jsx)(n.a,{href:"https://docs.quantum.ibm.com/api/qiskit/transpiler#layout-stage",children:"Layout Stage"})," untuk detail lebih lanjut."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:["Perutean. Tahap ini berjalan setelah tata letak diterapkan dan menyuntikkan Gate (seperti SWAP Gate) ke dalam Circuit asli untuk membuatnya kompatibel dengan konektivitas Backend. Lihat ",(0,t.jsx)(n.a,{href:"https://docs.quantum.ibm.com/api/qiskit/transpiler#routing-stage",children:"Routing Stage"})," untuk detail lebih lanjut."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:["Terjemahan. Tahap ini menerjemahkan Gate dalam Circuit ke set basis Backend target. Lihat ",(0,t.jsx)(n.a,{href:"https://docs.quantum.ibm.com/api/qiskit/transpiler#translation-stage",children:"Translation Stage"})," untuk detail lebih lanjut."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Optimasi. Tahap ini menjalankan loop optimasi utama berulang kali hingga kondisi (seperti mencapai kedalaman target tertentu) tercapai. Kita memiliki empat level optimasi berbeda untuk dipilih, yang dijelaskan di bawah ini."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Penjadwalan. Tahap ini untuk pass penjadwalan yang sadar perangkat keras. Pada level tinggi, penjadwalan bisa dianggap sebagai penyisipan penundaan ke dalam Circuit untuk memperhitungkan waktu idle pada qubit antara eksekusi instruksi."}),"\n"]}),"\n"]}),"\n",(0,t.jsxs)(n.p,{children:["Ada empat level optimasi mulai dari 0 hingga 3, di mana level optimasi yang lebih tinggi memerlukan lebih banyak waktu dan upaya komputasi tetapi mungkin menghasilkan Circuit yang lebih baik. Level optimasi 0 dimaksudkan untuk eksperimen karakterisasi perangkat dan, dengan demikian, hanya memetakan Circuit input ke batasan Backend target, tanpa melakukan optimasi apa pun. Level optimasi 3 menghabiskan upaya paling banyak untuk mengoptimalkan Circuit. Namun, karena banyak teknik optimasi dalam transpiler berbasis heuristik, menghabiskan lebih banyak upaya komputasi tidak selalu menghasilkan peningkatan kualitas Circuit output. Jika ini menarik lebih lanjut, lihat ",(0,t.jsx)(n.a,{href:"https://docs.quantum.ibm.com/api/qiskit/transpiler",children:"dokumentasi transpiler"})," dalam dokumentasi Qiskit."]}),"\n",(0,t.jsx)(n.h4,{id:"error-suppression",children:"Penekanan kesalahan"}),"\n",(0,t.jsx)(n.p,{children:"Langkah pertama dalam mengurangi kesalahan dalam Circuit adalah mengoptimalkan tata letak, perutean, dan meminimalkan jumlah Gate, yang sudah kita lakukan, baik menggunakan transpiler atau sendiri. Sekarang mari kita bahas beberapa metode penekanan kesalahan yang lebih canggih."}),"\n",(0,t.jsx)(n.p,{children:'Penekanan kesalahan mengacu pada kelas teknik yang mengubah Circuit selama kompilasi untuk meminimalkan kesalahan. Ini berbeda dari mitigasi kesalahan, yang akan kita bahas nanti di bagian "Eksekusi" di bawah ini. Dua bentuk penekanan kesalahan yang paling umum kita gunakan adalah dynamical decoupling dan Pauli twirling:'}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsx)(n.li,{children:"Dynamical decoupling digunakan untuk secara efektif membatalkan sebagian noise lingkungan yang diperkenalkan ketika qubit berada dalam keadaan idle. Dengan menerapkan serangkaian Gate pada waktu tertentu, kamu bisa membuat noise yang terakumulasi di satu bagian dari periode idle secara kasar membatalkan noise di bagian lainnya."}),"\n",(0,t.jsx)(n.li,{children:"Pauli twirling adalah cara menyisipkan Gate acak bukan untuk membatalkan noise, seperti dalam dynamical decoupling, tetapi untuk menyederhanakan noise. Dengan menyisipkan Gate acak, ini mencegah efek kesalahan yang berbeda menumpuk secepat mungkin, dan membuat noise lebih mudah dikarakterisasi, karena sekarang memiliki sifat stokastik. Metode ini juga membentuk dasar teknik mitigasi kesalahan yang kuat, yang akan kita bahas di bawah ini."}),"\n"]}),"\n",(0,t.jsx)(n.h3,{id:"execute",children:"Eksekusi"}),"\n",(0,t.jsx)(n.p,{children:"Sekarang kita siap untuk mengeksekusi program kuantum. Qiskit Runtime primitives menyediakan antarmuka ke perangkat keras IBM Quantum, dan mereka juga mengabstraksikan penekanan dan mitigasi kesalahan dari pengguna. Ada dua primitif yang bisa dipilih: Sampler dan Estimator."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://docs.quantum.ibm.com/api/qiskit-ibm-runtime/sampler",children:"Qiskit Runtime's Sampler"})," menjalankan Circuit berkali-kali pada perangkat kuantum, melakukan pengukuran pada setiap jalannya, dan merekonstruksi distribusi probabilitas dari string bit yang dipulihkan. Semakin banyak jalannya (atau shot) yang dilakukan, semakin akurat hasilnya, tetapi ini memerlukan lebih banyak waktu dan sumber daya kuantum. Secara khusus, ini menghitung probabilitas mendapatkan setiap keadaan basis standar yang mungkin dengan mengukur keadaan yang disiapkan oleh Circuit."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://docs.quantum.ibm.com/api/qiskit-ibm-runtime/estimator",children:"Qiskit Runtime's Estimator"})," menggunakan proses aljabar yang kompleks untuk memperkirakan nilai ekspektasi pada perangkat kuantum nyata dengan memecah observable menjadi kombinasi observable lain dengan eigenbasis yang diketahui."]}),"\n",(0,t.jsxs)(n.p,{children:["Langkah Eksekusi juga merupakan saat kita bisa memilih strategi ",(0,t.jsx)(n.em,{children:"mitigasi kesalahan"}),". ",(0,t.jsx)(n.em,{children:"Mitigasi kesalahan"})," mengacu pada teknik yang memungkinkan pengguna mengurangi kesalahan Circuit dengan memodelkan noise perangkat yang ada pada saat eksekusi. Biasanya, ini menghasilkan overhead pra-pemrosesan kuantum yang terkait dengan pelatihan model dan overhead pasca-pemrosesan klasik untuk memitigasi kesalahan dalam hasil mentah menggunakan model yang dihasilkan. Sebagai ganti overhead ini, kita bisa mendapatkan hasil yang jauh lebih akurat."]}),"\n",(0,t.jsx)(n.p,{children:"Ada beberapa teknik yang bisa kita implementasikan untuk mitigasi kesalahan. Kita akan membahas tiga, dalam urutan ketahanan terhadap kesalahan yang meningkat, tetapi juga, akibatnya, dalam urutan biaya komputasi yang meningkat. Perhatikan, bagaimanapun, bahwa ini adalah area penelitian aktif \u2014 jadi kita kemungkinan akan terus menemukan yang baru dan meningkatkan yang lama."}),"\n",(0,t.jsx)(n.p,{children:"Pada level ketahanan 0, transpiler tidak melakukan apa pun pada Circuit kamu."}),"\n",(0,t.jsx)(n.p,{children:"Pada level 1, ini memperkenalkan metode yang disebut Twirled Readout Error eXtinction (T-REX). T-REX menggunakan Pauli twirling, seperti yang dibahas di bagian penekanan kesalahan. Seperti yang disebutkan, menyisipkan Gate acak ke dalam Circuit bisa membuat bahkan noise yang sangat rumit dan sulit dimodelkan terlihat stokastik, dan jauh lebih mudah untuk diperhitungkan atau dikurangkan dalam pasca-pemrosesan."}),"\n",(0,t.jsx)(n.p,{children:"Pada level ketahanan 2, Zero Noise Extrapolation (ZNE) ditambahkan. Ini adalah teknik populer yang telah kita miliki banyak keberhasilan baru-baru ini. Ide di balik ZNE mungkin sedikit mengejutkan \u2014 kita sebenarnya menambahkan noise di atas yang sudah ada! Tetapi ini memungkinkan kita mengekstrapolasi ke arah sebaliknya, untuk memprediksi seperti apa hasilnya jika ada lebih sedikit dan lebih sedikit noise."}),"\n",(0,t.jsx)(n.p,{children:"Menambahkan noise bisa dilakukan dengan beberapa cara yang berbeda. Misalnya, kita bisa meregangkan Gate untuk membuatnya lebih panjang dan karenanya lebih rentan kesalahan, atau menjalankan lebih banyak Gate yang pada akhirnya menghasilkan operasi identitas, sehingga Circuit tidak berubah secara fungsional tetapi kita sengaja mengambil sampel lebih banyak noise. Namun kamu harus melakukan ini untuk setiap Circuit dan setiap nilai ekspektasi yang ingin kamu pantau \u2014 jadi kamu bisa melihat betapa mahalnya secara komputasi."}),"\n",(0,t.jsx)(n.p,{children:"Satu jenis spesifik ZNE disebut Probabilistic Error Amplification (PEA). Setelah kita mempelajari model noise untuk suatu Gate, PEA bekerja dengan mengambil sampel kesalahan dari model noise tersebut dan sengaja menyuntikkannya ke dalam Circuit. Ini belum tersedia di Qiskit, tetapi akan ada nanti tahun ini."}),"\n",(0,t.jsx)(n.p,{children:"Bentuk mitigasi kesalahan terakhir yang akan kita bahas adalah Probabilistic Error Cancellation (PEC). Alih-alih berada di level ketahanan ke-3, PEC adalah kemampuan khusus yang harus kamu aktifkan secara manual di Qiskit, karena sumber daya komputasi yang diperlukan tidak berkembang dengan sangat baik dibandingkan dengan teknik mitigasi kesalahan lainnya. Kamu mulai dengan mempelajari noise yang mempengaruhi Circuit kamu \u2014 jalankan sirkuit noise-learning atau noise-characterization untuk setiap lapisan unik Gate dua qubit dalam Circuit kamu. Hasil ini memungkinkanmu mendeskripsikan noise dalam hal operator Pauli. Setelah kamu mengetahui suku-suku noise ini, kamu bisa memodifikasi Circuit kamu sehingga mereka secara efektif memiliki Gate Pauli sebaliknya yang dibangun untuk membatalkan saluran noise ini. Dalam beberapa hal, prosesnya mirip dengan cara headphone peredam noise bekerja. Namun, cara ini untuk membatalkan noise sangat mahal, dengan waktu berjalan yang tumbuh dengan cepat dan secara eksponensial dalam jumlah Gate, sehingga mungkin bukan pilihan terbaik untuk Circuit yang sangat besar."}),"\n",(0,t.jsx)(n.h3,{id:"post-process",children:"Pasca-proses"}),"\n",(0,t.jsx)(n.p,{children:"Tahap pasca-proses adalah saat kita memvisualisasikan dan menganalisis output dari Circuit kuantum kita. Ada sejumlah alat Qiskit yang tersedia untuk melakukan ini, seperti modul visualisasi dan quantum-info. Kita tidak akan membahas ini di sini, tetapi kita akan melihat modul-modul ini beraksi saat kita menyelami beberapa contoh aplikasi dalam pelajaran-pelajaran mendatang."}),"\n",(0,t.jsx)(n.h2,{id:"conclusion",children:"Kesimpulan"}),"\n",(0,t.jsx)(n.p,{children:"Semoga pelajaran ini memberimu tur singkat tentang pertimbangan dan alur kerja utama yang kita gunakan saat ingin menjalankan komputasi kuantum skala utilitas. Penuh dengan informasi, dan banyak dari itu tidak akan langsung dipahami sampai kita melihat beberapa contoh nyata di mana konsep-konsep teoritis ini dipraktikkan. Jadi, itulah yang akan menjadi sisa kursus ini. Lagipula, kursus ini bukan disebut Quantum Computing in Practice tanpa alasan!"}),"\n",(0,t.jsx)(n.p,{children:"Lain kali, kita akan melihat contoh spesifik cara menggunakan alur kerja Qiskit patterns untuk merancang dan menjalankan Circuit kuantum yang memecahkan masalah klasik dari teori graf yang disebut MaxCut."})]})}function d(a={}){const{wrapper:n}={...(0,u.R)(),...a.components};return n?(0,t.jsx)(n,{...a,children:(0,t.jsx)(l,{...a})}):l(a)}},77815(a,n,i){i.d(n,{A:()=>e});const e=i.p+"assets/images/circuitdepth-e2f15da4f6d03fbe250110f56450f666.avif"},54776(a,n,i){i.d(n,{A:()=>e});const e="data:image/avif;base64,"},28453(a,n,i){i.d(n,{R:()=>s,x:()=>k});var e=i(96540);const t={},u=e.createContext(t);function s(a){const n=e.useContext(u);return e.useMemo(function(){return"function"==typeof a?a(n):{...n,...a}},[n,a])}function k(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(t):a.components||t:s(a.components),e.createElement(u.Provider,{value:n},a.children)}}}]);